PRB_CSS = [
    ('PR-B/1 dashboard+lists+pipeline', '/* ==========================================================================\n   Modern UI Revamp - PR-B - Worker 1: Dashboard + List pages + Sales Pipeline\n   (prb1.css)\n\n   Token-only additions. Load AFTER styles.css (or append below it) so these\n   rules win same-specificity ties against the legacy page CSS.\n\n   Every value below is a var(--token), a color-mix() of tokens, or a\n   non-color keyword (transparent / inherit / none). No hex literals, no\n   functional color notation, no px radii, no literal shadows. Muted text uses\n   --muted-foreground and muted surfaces use --secondary (never --muted).\n   ========================================================================== */\n\n/* ---- Dashboard greeting: subtle animated gradient text (Magic UI) ---- */\n.prb-greeting{\n  background:linear-gradient(100deg,var(--foreground) 25%,var(--primary) 50%,var(--foreground) 75%);\n  background-size:220% auto;\n  -webkit-background-clip:text;\n  background-clip:text;\n  color:transparent;\n  animation:prb-greeting-shift 9s ease-in-out infinite;\n}\n@keyframes prb-greeting-shift{\n  0%,100%{background-position:0% center}\n  50%{background-position:100% center}\n}\n\n/* ---- Border beam for the primary KPI card (Magic UI) ---- */\n@property --prb-beam-angle{\n  syntax:"<angle>";\n  initial-value:0deg;\n  inherits:false;\n}\n.prb-beam{position:relative}\n.prb-beam::after{\n  content:"";\n  position:absolute;\n  inset:-1px;\n  border-radius:inherit;\n  padding:2px;\n  pointer-events:none;\n  background:conic-gradient(from var(--prb-beam-angle),transparent 0deg,color-mix(in srgb,var(--primary) 85%,transparent) 45deg,transparent 90deg);\n  -webkit-mask:linear-gradient(var(--foreground) 0 0) content-box,linear-gradient(var(--foreground) 0 0);\n  -webkit-mask-composite:xor;\n  mask-composite:exclude;\n  animation:prb-beam-spin 5s linear infinite;\n}\n@keyframes prb-beam-spin{\n  to{--prb-beam-angle:360deg}\n}\n\n/* ---- KPI cards ---- */\n.kpi-grid{gap:var(--space-4)}\n.prb-kpi{\n  appearance:none;\n  display:flex;\n  flex-direction:column;\n  align-items:flex-start;\n  gap:var(--space-2);\n  padding:var(--space-5);\n  margin:0;\n  text-align:left;\n  color:var(--foreground);\n  cursor:pointer;\n  transition:transform var(--motion-base) ease,box-shadow var(--motion-base) ease,border-color var(--motion-fast) ease;\n}\n.prb-kpi:hover{\n  transform:translateY(-2px);\n  box-shadow:var(--shadow-md);\n  border-color:color-mix(in srgb,var(--primary) 40%,var(--border));\n}\n.prb-kpi:focus-visible{outline:2px solid var(--ring);outline-offset:2px}\n.prb-kpi-label{font-size:var(--text-sm);font-weight:600;color:var(--muted-foreground)}\n.prb-kpi-value{font-size:var(--text-2xl);font-weight:800;letter-spacing:-0.02em;color:var(--foreground)}\n.prb-kpi-link{font-size:var(--text-xs);font-weight:600;color:var(--primary)}\n\n/* ---- Card header row: title left, action link right ---- */\n.prb-card-head{display:flex;align-items:center;justify-content:space-between;gap:var(--space-3)}\n.prb-card-head h3{margin:0;font-size:var(--text-base);font-weight:700;letter-spacing:-0.01em}\n\n/* ---- Dashboard list rows (record-list widgets, pipeline snapshot, tasks) ---- */\n.prb-row{\n  padding:var(--space-3) var(--space-2);\n  border-top:1px solid var(--border);\n  border-radius:var(--radius-sm);\n  transition:background-color var(--motion-fast) ease;\n}\n.prb-row:first-child{border-top:0}\n.prb-row:hover{background:color-mix(in srgb,var(--accent) 55%,transparent)}\n.prb-row[data-open-record]{cursor:pointer}\n.prb-row-spread{display:flex;justify-content:space-between;align-items:baseline;gap:var(--space-3)}\n\n/* ---- Sales pipeline kanban ---- */\n.prb-kanban-col{min-height:540px;display:flex;flex-direction:column}\n.prb-kanban-head{display:flex;align-items:center;justify-content:space-between;gap:var(--space-2);padding:var(--space-4) var(--space-4) var(--space-3)}\n.prb-kanban-head h3{margin:0;font-size:var(--text-sm);font-weight:700;letter-spacing:-0.01em}\n.prb-kanban-body{display:flex;flex-direction:column;gap:var(--space-3);padding:0 var(--space-4) var(--space-4);flex:1}\n.prb-deal{\n  padding:var(--space-4);\n  display:flex;\n  flex-direction:column;\n  gap:var(--space-1);\n  transition:transform var(--motion-base) ease,box-shadow var(--motion-base) ease,border-color var(--motion-fast) ease;\n}\n.prb-deal:hover{\n  transform:translateY(-2px);\n  box-shadow:var(--shadow-md);\n  border-color:color-mix(in srgb,var(--primary) 40%,var(--border));\n}\n.prb-deal:active{transform:translateY(0) scale(.99)}\n.prb-deal-title{font-weight:700;font-size:var(--text-sm);color:var(--foreground)}\n.prb-deal-value{font-weight:800;margin-top:var(--space-2);color:var(--foreground)}\n.prb-deal .actions{margin-top:var(--space-2)}\n\n/* ---- List pages: modern table ---- */\n.table-wrap{\n  background-color:var(--card);\n  border-color:var(--border);\n  border-radius:var(--radius-lg);\n  background-image:\n    linear-gradient(to right,var(--card) 30%,transparent),\n    linear-gradient(to right,transparent,var(--card) 70%),\n    linear-gradient(to right,color-mix(in srgb,var(--foreground) 12%,transparent),transparent),\n    linear-gradient(to left,color-mix(in srgb,var(--foreground) 12%,transparent),transparent);\n}\n.table thead th{\n  position:sticky;\n  top:0;\n  z-index:2;\n  background:var(--secondary);\n  color:var(--muted-foreground);\n}\n.table tbody td{\n  border-color:var(--border);\n  transition:background-color var(--motion-fast) ease;\n}\n.table tbody tr:hover td{background:color-mix(in srgb,var(--accent) 45%,transparent)}\n.prb-group-row td{\n  background:var(--secondary);\n  color:var(--secondary-foreground);\n  font-weight:600;\n  font-size:var(--text-xs);\n  text-transform:uppercase;\n  letter-spacing:.05em;\n}\n.bulk-check{accent-color:var(--primary);width:var(--space-4);height:var(--space-4);cursor:pointer}\n.empty{color:var(--muted-foreground)}\n\n/* ---- List page toolbar bits ---- */\n.breadcrumbs{color:var(--muted-foreground)}\n.breadcrumbs button{color:var(--primary)}\n\n/* ---- Dashboard "+ New" quick-create menu ---- */\n.quick-menu{background:var(--popover);border-color:var(--border)}\n.quick-menu button{color:var(--foreground)}\n.quick-menu button:hover{background:var(--accent);color:var(--accent-foreground)}\n\n/* ---- Reduced motion: static greeting + beam ---- */\n@media (prefers-reduced-motion:reduce){\n  .prb-greeting{animation:none;background:none;color:var(--foreground);-webkit-background-clip:border-box;background-clip:border-box}\n  .prb-beam::after{animation:none}\n}\n'),
    ('PR-B/2 record detail', '/* Modern UI PR-B2 - Record detail pages (Worker 2).\n   shadcn-style reskin of Company / Contact / generic record detail:\n   record header, detail field grid, related lists, activity timeline.\n   100% token-driven: no hardcoded colors, radii, or shadows. */\n\n/* ---- Record header (replaces .rule360-header) ---- */\n.record-head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;flex-wrap:wrap;padding:24px;margin-bottom:20px}\n.record-head-id{display:flex;gap:16px;align-items:flex-start;min-width:0}\n.record-head-avatar{width:56px;height:56px;font-size:var(--text-xl);border-radius:var(--radius-lg);flex-shrink:0}\n.record-head-titles{min-width:0}\n.record-head-titles h1{margin:2px 0 6px;font-size:var(--text-2xl);letter-spacing:-.02em;color:var(--foreground)}\n.record-head-meta{display:flex;align-items:center;gap:14px;flex-wrap:wrap;font-size:var(--text-sm);color:var(--muted-foreground);margin-top:6px}\n.record-head-meta .badge{background:var(--secondary);color:var(--secondary-foreground)}\n.record-head .muted{color:var(--muted-foreground)}\n.record-head-actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center}\n\n/* ---- Breadcrumbs on detail pages ---- */\n.prb2-crumbs{color:var(--muted-foreground);font-size:var(--text-xs);margin-bottom:12px}\n.prb2-crumbs button{color:var(--primary);font-weight:600}\n.prb2-crumbs button:hover{text-decoration:underline}\n\n/* ---- Card titles (PR-A .card ships no title class) ---- */\n.card-title{font-size:var(--text-base);font-weight:700;margin:0;color:var(--card-foreground);display:flex;align-items:center;gap:8px}\n.prb2-card-head-split{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}\n\n/* ---- Detail field grid: definition-list rows ---- */\n.prb2-field-group{margin-bottom:18px}\n.prb2-field-group:last-child{margin-bottom:0}\n.prb2-field-group-title{font-size:var(--text-xs);font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--muted-foreground);margin:0 0 4px}\n.prb2-field-grid{display:grid;grid-template-columns:repeat(var(--prb2-cols,2),minmax(0,1fr));gap:0 24px;margin:0}\n.prb2-field-row{padding:9px 0;border-bottom:1px solid var(--border)}\n.prb2-field-row:last-child{border-bottom:0}\n.prb2-field-row-full{grid-column:1/-1}\n.prb2-field-row dt{font-size:var(--text-xs);font-weight:600;color:var(--muted-foreground);margin-bottom:2px}\n.prb2-field-row dd{margin:0;font-size:var(--text-sm);color:var(--foreground);overflow-wrap:anywhere}\n\n/* ---- Related lists (.rule360-related-card markup kept as-is; restyled) ---- */\n.rule360-related-card{background:var(--card);color:var(--card-foreground);border:1px solid var(--border);border-radius:var(--radius-lg);box-shadow:var(--shadow-sm);padding:0;margin-bottom:16px;overflow:hidden}\n.rule360-related-card h4{margin:0;padding:16px 18px 0;font-size:var(--text-sm);font-weight:700}\n.rule360-related-row{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:10px 18px;border-bottom:1px solid var(--border);font-size:var(--text-sm);transition:background-color var(--motion-fast) ease}\n.rule360-related-row:last-child{border-bottom:0}\n.rule360-related-row:hover{background:var(--accent)}\n.rule360-related-row a{color:var(--primary);font-weight:700;cursor:pointer}\n.rule360-related-card .muted{color:var(--muted-foreground)}\n\n/* ---- Activity timeline ---- */\n.prb2-activity-fields{margin:0 0 16px}\n[data-activity-panel] .field label{color:var(--foreground)}\n.prb2-timeline{margin:0;padding:4px 0 0}\n.prb2-tl-item{position:relative;display:flex;gap:14px;padding:0 0 20px 26px}\n.prb2-tl-item:last-child{padding-bottom:2px}\n.prb2-tl-item::before{content:"";position:absolute;left:8px;top:20px;bottom:0;width:2px;background:var(--border)}\n.prb2-tl-item:last-child::before{display:none}\n.prb2-tl-dot{position:absolute;left:3px;top:5px;width:12px;height:12px;border-radius:var(--radius-full);box-shadow:0 0 0 3px var(--card),0 0 0 4.5px var(--border)}\n.prb2-tl-email{background:var(--info)}\n.prb2-tl-call{background:var(--success)}\n.prb2-tl-message{background:var(--secondary-foreground)}\n.prb2-tl-body{min-width:0;flex:1}\n.prb2-tl-head{display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;font-size:var(--text-sm)}\n.prb2-tl-dir{font-size:var(--text-xs);color:var(--muted-foreground);text-transform:capitalize}\n.prb2-tl-notes{margin-top:4px;font-size:var(--text-sm);color:var(--foreground)}\n.prb2-tl-meta{font-size:var(--text-xs);color:var(--muted-foreground);margin-top:4px}\n\n/* ---- Products and services lines card (quotes / orders / invoices) ---- */\n.prb2-lines .table-wrap{border:0;border-radius:0}\n.prb2-lines .table th{background:var(--secondary);color:var(--muted-foreground)}\n.prb2-lines .table tr:hover td{background:var(--accent)}\n.prb2-line-total{display:flex;justify-content:flex-end;align-items:baseline;gap:12px;font-size:var(--text-lg);font-weight:700;color:var(--foreground);padding:16px 4px 0}\n.prb2-line-balance{font-size:var(--text-sm);font-weight:400;color:var(--muted-foreground)}\n\n/* ---- Page Builder sections inside Overview inherit card styling ---- */\n.prb2-detail .panel{background:var(--card);color:var(--card-foreground);border:1px solid var(--border);border-radius:var(--radius-lg);box-shadow:var(--shadow-sm)}\n\n@media(max-width:720px){\n .record-head{flex-direction:column}\n .prb2-field-grid{grid-template-columns:1fr}\n}\n'),
    ('PR-B/3 ontology graph + object 360', "/* ==========================================================================\n   Modern UI Revamp PR-B · Worker 3 — Ontology Graph + Object 360\n   Token-only additions. Every value resolves through the §4 token set;\n   no hardcoded colors, radii, or shadows. Loaded after styles.css.\n   ========================================================================== */\n\n/* Toolbar search: the .input component brings token chrome; keep the\n   toolbar's designed width (the path-bar pickers share this class). */\n.ontology-search-input{width:220px;max-width:100%}\n\n/* Badge-styled toggle chips render as buttons: restore the pointer cursor\n   and a token-driven focus ring. */\nbutton.badge{cursor:pointer}\nbutton.badge:focus-visible{outline:2px solid var(--ring);outline-offset:2px}\n\n/* Component picker row: side-by-side labeled selects using .select. */\n.form-row{display:flex;gap:12px;flex-wrap:wrap;align-items:flex-end;margin-bottom:4px}\n.form-row label{display:flex;flex-direction:column;gap:6px;flex:1 1 180px;font-size:var(--text-sm);font-weight:600;color:var(--foreground)}\n.form-row .select{width:100%}\n\n/* Compact selects that sit inside toolbar rows keep their auto width. */\n.o360-depth .select{width:auto}\n#depSimPicker .select{width:auto}\n\n/* Detail panel and the Object 360 inspector card ride on .card; keep\n   their panel metrics on top of the component chrome. */\n.ontology-detail-panel.card{width:300px}\n#o360InspectorCard.card{width:290px}\n"),
]


def apply_reps(path, reps):
    with open(path, encoding='utf-8') as f:
        src = f.read()
    for name, old, new, expected in reps:
        n = src.count(old)
        if n != expected:
            sys.exit('ANCHOR FAIL [%s] (%s): expected %d, found %d' % (name, path, expected, n))
        src = src.replace(old, new, n if expected != 1 else 1)
        print('ok [%s] (%s)' % (name, path))
    with open(path, 'w', encoding='utf-8') as f:
        f.write(src)


def main():
    apply_reps(APP, JS_REPLACEMENTS)
    apply_reps(CSS, CSS_REPLACEMENTS)
    with open(CSS, 'a', encoding='utf-8') as f:
        for tag, css in PRB_CSS:
            f.write('\n\n/* ===== Modern UI %s ===== */\n' % tag)
            f.write(css)
            print('appended [%s] to %s' % (tag, CSS))
    print('PR-B TRANSFORM COMPLETE')


if __name__ == '__main__':
    main()
